const august11ResearchPosts: readonly ResearchPost[] = [
  { slug: 'hr-employee-data-retention-review', title: 'Employee Data Retention Reviews: Align Records With Purpose', excerpt: 'A source-backed way for HR teams to review retention needs without keeping every copy forever.', published: '2026-08-12', sections: [{ heading: 'Research question', body: 'How can a small HR team decide which records to retain, where to keep them, and when to review them? The answer starts with purpose, record category, owner, and the applicable retention rule.' }, { heading: 'Evidence and model', body: 'Records guidance and privacy frameworks point to a documented inventory, defined owner, access boundary, review date, and disposition evidence. A support role can prepare the inventory, while the HR or legal owner approves the rule.' }, { heading: 'Operational implication', body: 'Separate the authoritative record from working copies. Log the record class, system of record, trigger date, review date, and exception owner; never infer a disposal date from file age alone.' }], sources: august11ResearchSources },
  { slug: 'hr-employee-status-change-reconciliation', title: 'Employee Status Changes: Reconcile the Record Across Systems', excerpt: 'How to reduce downstream HR errors when a status, manager, location, or work arrangement changes.', published: '2026-08-12', sections: [{ heading: 'Research question', body: 'What makes an employee-status change reliable after the request is approved? The change must have an authoritative source, a named approver, a controlled update, and a reconciliation across dependent systems.' }, { heading: 'Evidence and model', body: 'Internal-control guidance supports recording the request, approval, effective date, changed fields, system update, and post-change check. The administrator prepares and reconciles; the authorized owner decides whether the change is valid.' }, { heading: 'Operational implication', body: 'Use a change register that distinguishes requested, approved, applied, and reconciled. Keep rejected or superseded requests visible so later reviewers can explain the final state.' }], sources: august11ResearchSources },
  { slug: 'hr-employee-request-response-evidence', title: 'Employee Request Response Evidence: Measure Accuracy With Context', excerpt: 'A practical research model for reviewing HR request handling without rewarding unsafe speed.', published: '2026-08-12', sections: [{ heading: 'Research question', body: 'Which evidence shows that an HR request was handled well? Response time matters, but it must be read alongside accuracy, privacy handling, escalation quality, and whether the request was actually resolved.' }, { heading: 'Evidence and model', body: 'Privacy and records guidance support a minimum dataset: category, received time, owner, approved source, response status, escalation reason, and closure evidence. Keep personal narratives out of aggregate reporting.' }, { heading: 'Operational implication', body: 'Review a sample by risk category, not only by speed. A fast response that gives an unauthorized answer should count as a control failure and route to owner review.' }], sources: august11ResearchSources },
  { slug: 'hr-recruiting-records-retention-map', title: 'Recruiting Records Retention: Map the Evidence Before the Role Closes', excerpt: 'A source-backed framework for keeping recruiting records findable, consistent, and appropriately limited.', published: '2026-08-12', sections: [{ heading: 'Research question', body: 'How should a recruiting team preserve process evidence without collecting unnecessary candidate information? Define the hiring event, record category, owner, access group, and retention trigger.' }, { heading: 'Evidence and model', body: 'Employment-record guidance makes consistent preservation important, while privacy principles require purpose-limited access. Keep the approved role, stage history, scorecards, communications, and disposition evidence in defined locations.' }, { heading: 'Operational implication', body: 'A coordinator can check completeness and link records to the correct requisition. They should not rewrite interviewer judgment, infer a selection decision, or move sensitive material into a general tracker.' }], sources: august11ResearchSources },
  { slug: 'hr-policy-acknowledgment-exception-review', title: 'Policy Acknowledgment Exceptions: Make the Unresolved Work Visible', excerpt: 'How HR teams can distinguish delivery, acknowledgment, refusal, and exception states.', published: '2026-08-12', sections: [{ heading: 'Research question', body: 'What does a reliable policy acknowledgment record need to show? It should identify the approved version, audience, delivery event, acknowledgment signal, exception owner, and next review date.' }, { heading: 'Evidence and model', body: 'Governance and records guidance support version control and evidence of communication. A status of pending is not the same as refused, failed delivery, or an approved exception.' }, { heading: 'Operational implication', body: 'Keep the original delivery and acknowledgment events. Route missing or disputed acknowledgments to the policy owner instead of repeatedly sending untracked reminders or changing the status by assumption.' }], sources: august11ResearchSources },
  { slug: 'hr-manager-approval-delegation-review', title: 'Manager Approval Delegation: Review Authority Before It Expires', excerpt: 'A control model for temporary HR approval delegation, with clear scope and closeout evidence.', published: '2026-08-12', sections: [{ heading: 'Research question', body: 'When can a delegated manager approval be trusted? The delegation needs a named delegator, delegate, scope, start and end dates, affected workflow, and a recorded closeout.' }, { heading: 'Evidence and model', body: 'Access-control and internal-control guidance support least privilege, explicit authorization, and periodic review. A coordinator may maintain the register, but cannot broaden its scope or extend it without the authorized owner.' }, { heading: 'Operational implication', body: 'Check delegation status at the point of action, not only when the delegation is created. Preserve superseded entries so a reviewer can distinguish a valid approval from an expired one.' }], sources: august11ResearchSources },
  { slug: 'hr-onboarding-document-completeness-review', title: 'Onboarding Document Completeness: Check Fields Without Becoming the Approver', excerpt: 'A source-backed method for finding missing onboarding information while protecting decision ownership.', published: '2026-08-12', sections: [{ heading: 'Research question', body: 'Which checks improve onboarding completeness without turning administration into eligibility or legal judgment? Check required fields, source, due date, owner, and approved destination.' }, { heading: 'Evidence and model', body: 'Employment and privacy guidance support collecting only what the process requires and keeping sensitive documents in approved systems. Completion status is useful evidence; a copied document is not always necessary.' }, { heading: 'Operational implication', body: 'Separate missing-field follow-up from questions about eligibility, accommodation, or policy interpretation. Those exceptions belong with the qualified HR owner.' }], sources: august11ResearchSources },
  { slug: 'hr-hris-audit-log-review', title: 'HRIS Audit-Log Reviews: Turn System Events Into Owner-Ready Evidence', excerpt: 'How to review HRIS changes for unexpected activity, missing approvals, and unresolved exceptions.', published: '2026-08-12', sections: [{ heading: 'Research question', body: 'What makes an HRIS audit-log review useful to an HR owner? It should connect an event to a user, record, field, timestamp, reason, approval, and expected outcome.' }, { heading: 'Evidence and model', body: 'Security frameworks treat logging and review as governance signals. Filter routine noise, preserve the original event, classify anomalies, and route any unexplained change to the system or data owner.' }, { heading: 'Operational implication', body: 'Do not edit logs to make a report cleaner. Produce a separate review record with the query window, reviewer, sampled events, exceptions, and escalation result.' }], sources: august11ResearchSources },
  { slug: 'hr-employee-file-access-exception-review', title: 'Employee-File Access Exceptions: Review the Why, Not Just the Who', excerpt: 'A practical research approach to investigating unusual access without expanding exposure.', published: '2026-08-12', sections: [{ heading: 'Research question', body: 'How should HR investigate an unusual employee-file access event? Start with purpose, role, record category, time, approved task, and the minimum evidence needed to explain the event.' }, { heading: 'Evidence and model', body: 'Privacy and access-control guidance support reviewing access against a defined business need. The reviewer should work from metadata and approved logs before opening sensitive content.' }, { heading: 'Operational implication', body: 'Route unclear or high-risk events to security or the HR owner. A support administrator can assemble the evidence packet but should not decide whether an exception is acceptable.' }], sources: august11ResearchSources },
  { slug: 'hr-people-ops-reporting-close-controls', title: 'People-Ops Reporting Close: Freeze Definitions Before Comparing Results', excerpt: 'A research model for closing recurring HR reports with stable definitions and visible exceptions.', published: '2026-08-12', sections: [{ heading: 'Research question', body: 'Why do recurring HR reports drift even when the spreadsheet formula appears unchanged? Population, effective dates, source freshness, exclusions, and definitions can change silently.' }, { heading: 'Evidence and model', body: 'Measurement methodology and internal-control guidance support versioned definitions, a fixed reporting window, source checks, reconciliation, and owner signoff. Document the reason for any restatement.' }, { heading: 'Operational implication', body: 'Close the reporting window before explaining trends. Show unresolved exceptions rather than excluding them, and keep the metric definition alongside the report so another reviewer can reproduce it.' }], sources: august11ResearchSources },
] as const;

